            ++count;
        }
    if (!parse_hex(fields[0], &out->pc) || out->pc % 4)
        return "pc";
    out->kind = -1;
    for (int i = 0; i < 7; ++i)
        if (strcmp(fields[1], classes[i]) == 0)
            out->kind = i;
    int registers[3] = {parse_register(fields[2]), parse_register(fields[3]),
                        parse_register(fields[4])};
    out->rd = registers[0];
    out->rs1 = registers[1];
    out->rs2 = registers[2];
    out->next = out->taken ? out->target : out->pc + 4;
    return NULL;
